package com.rationportal.model; import jakarta.persistence.*; import java.math.BigDecimal; @Entity @Table(name="family_members") public class FamilyMember { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="ration_card_id", nullable=false) private RationCard rationCard; @Column(name="member_id", unique=true, nullable=false) private String memberId; @Column(nullable=false) private String name; @Column(nullable=false) private Integer age; private String gender; private String relationship; @Column(name="rice_quota_kg", nullable=false) private BigDecimal riceQuotaKg; public Long getId(){return id;} public RationCard getRationCard(){return rationCard;} public void setRationCard(RationCard rationCard){this.rationCard=rationCard;} public String getMemberId(){return memberId;} public void setMemberId(String memberId){this.memberId=memberId;} public String getName(){return name;} public void setName(String name){this.name=name;} public Integer getAge(){return age;} public void setAge(Integer age){this.age=age;} public String getGender(){return gender;} public void setGender(String gender){this.gender=gender;} public String getRelationship(){return relationship;} public void setRelationship(String relationship){this.relationship=relationship;} public BigDecimal getRiceQuotaKg(){return riceQuotaKg;} public void setRiceQuotaKg(BigDecimal riceQuotaKg){this.riceQuotaKg=riceQuotaKg;} }
